entities.x:
$fn ({hass}) => {
  const xs = [];
  for (let t = 15; t <= 35.01; t += 0.25) xs.push(t);
  return xs;
}

entities.y:
$fn ({hass}) => {
  const target = parseFloat(hass.states['sensor.active_vpd_target']?.state);
  if (isNaN(target)) return [];
  const ys = [];
  for (let t = 15; t <= 35.01; t += 0.25) {
    const svp = 0.61078 * Math.exp((17.27 * t) / (t + 237.3));
    ys.push(100 * (1 - target / svp));
  }
  return ys;
}

